input.command:
cat > .slop.json <<'E'
{
  "overrides": [
    { "files": ["README.md"], "ignore": ["chatbot"] },
    { "files": ["docs/fr/**", "docs/de/**"], "ignore": ["dash", "title-case-heading"] }
  ]
}
E
npm run lint:prose 2>&1 | grep -E "^(README|docs)"
rm docs/guide.md; npm run lint:prose >/dev/null 2>&1; echo without-guide $?
printf '# T\n\nA plain sentence — with a dash in it, written long enough to be graded as prose for the check here.\n' > docs/fr/x.md; npm run lint:prose >/dev/null 2>&1; echo fr-dash $?; rm docs/fr/x.md
printf '# T\n\nIn today'"'"'s fast-paced world this is a testament to seamless robust work. Let me know if you have questions!\n' > docs/new.md; npm run lint:prose >/dev/null 2>&1; echo new-bad $?; rm docs/new.md

